body,
html {
  height: 100%;
  min-height: 100%;
  font-family: 'Noto Sans JP', sans-serif;
  font-weight: 500;
  font-size: 15px;
  padding: 0;
  margin: 0;
}

body {
  background: #fff;
  overflow-x: hidden;
  min-width: 320px;
  color: #101525;
}

body * {
  box-sizing: border-box;
  outline: none !important;
}

.wrapper {
  padding-top: 195px;
}

.wrap {
  min-width: 320px;
  padding: 0;
  margin: 0 auto;
}

@media screen and (max-width: 1200px) {
}

section {
  padding-left: 180px;
  padding-right: 180px;
}

footer {
  padding: 62px 116px 68px 180px;
}

footer.style-1 {
  background: #231F51;
}

footer.style-2 {
  background: #E3EFFE;
}

footer.style-3 {
  background: red;
}

footer.style-4 {
  background: red;
}

footer .social {
  padding-top: 5px;
}

footer .social a {
  font-size: 23px;
  color: #fff;
}

footer .social a:hover {
  color: #F7796A;
}

footer .copy {
  opacity: 0.35;
  color: #FFF;
  font-size: 11px;
  line-height: 50px;
}

footer .copy a {
  color: #FFF;
}

footer .copy a:hover {
  text-decoration: underline;
}

footer .copy span {
  display: inline-block;
  margin: 0 20px;
}

footer .menu {
  display: block;
  padding: 0;
  margin: 0 0 230px;
  font-size: 0;
}

footer .menu > li {
  display: inline-block;
  vertical-align: top;
  padding: 12px 0;
  position: relative;
}

footer .menu > li:after {
  content: "";
  display: block;
  width: 50px;
  height: 4px;
  background: #fff;
  position: absolute;
  left: 0;
  bottom: 0;
}

footer .menu > li > a {
  font-size: 15px;
  font-weight: 900;
  letter-spacing: 1px;
  line-height: 1.5;
  text-transform: uppercase;
  color: #fff;
  text-decoration: none;
}

footer .menu > li > a:hover {
  color: #F7796A;
}

footer .menu > li.open .sub-menu {
  display: block;
}

footer .menu > li.open .sub-menu:after {
  content: "";
  display: block;
  width: 50px;
  height: 4px;
  background: #F7796A;
  position: absolute;
  left: 0;
  bottom: -20px;
}

footer .menu > li.open:after {
  display: none;
}

footer .menu > li .sub-menu {
  display: none;
  padding: 0;
  margin: 0;
  position: absolute;
  left: 0;
  top: 62px;
  width: 100%;
}

footer .menu > li .sub-menu li {
  display: block;
}

footer .menu > li .sub-menu li a {
  color: #FFF;
  font-size: 15px;
  font-weight: 500;
  line-height: 40px;
  white-space: nowrap;
}

footer.style-2 .social a {
  color: #101525;
}

footer.style-2 .copy {
  color: #101525;
}

footer.style-2 .copy a {
  color: #101525;
}

footer.style-2 .menu > li:after {
  background: #101525;
}

footer.style-2 .menu > li > a {
  color: #101525;
}

footer.style-2 .menu > li .sub-menu li a {
  color: #101525;
}

header {
  background: #fff;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
}

header .top-bar {
  padding: 30px 100px 33px 113px;
}

header .top-bar .logo {
  display: block;
  color: #101525;
  font-size: 25px;
  font-weight: 900;
  line-height: 1;
}

header .top-bar .logo span {
  display: inline-block;
  height: 52px;
  width: 52px;
  background-color: #E3EFFE;
  vertical-align: middle;
  margin-right: 14px;
  border-radius: 50%;
}

header .top-bar .phone,
header .top-bar .basket {
  color: #101525;
  font-size: 15px;
  font-weight: 900;
  letter-spacing: 0.75px;
  line-height: 22px;
  display: inline-block;
  margin-left: 43px;
  position: relative;
}

header .top-bar .phone i,
header .top-bar .basket i {
  font-size: 25px;
  vertical-align: middle;
}

header .top-bar .phone .fa-phone,
header .top-bar .basket .fa-phone {
  transform: rotate(93deg);
  position: relative;
  top: -2px;
  margin-left: 10px;
}

header .basket {
  display: inline-block;
  margin-left: 43px;
  color: #101525;
  position: relative;
  cursor: pointer;
}

header .basket i {
  font-size: 25px;
  vertical-align: middle;
  position: relative;
  z-index: 2;
}

header .basket span {
  display: block;
  color: #101525;
  font-size: 12px;
  font-weight: 900;
  line-height: 18px;
  white-space: nowrap;
  vertical-align: middle;
  position: absolute;
  top: -7px;
  left: 20px;
  z-index: 1;
}

header .basket span:before {
  content: "";
  display: inline-block;
  height: 16px;
  width: 16px;
  background-color: #F97866;
  margin-right: 4px;
  border-radius: 50%;
  vertical-align: middle;
}

header .basket.open:before {
  content: "";
  display: block;
  height: 8px;
  width: 8px;
  background: #F7796A;
  border-radius: 50%;
  position: absolute;
  top: 100%;
  left: 50%;
  margin-left: -3px;
}

header .basket.open:after {
  content: "";
  display: block;
  height: 56px;
  width: 2px;
  background: #F7796A;
  position: absolute;
  top: 100%;
  left: 50%;
  margin-top: 5px;
}

header .down-bar {
  background: #E3EFFE;
  padding: 18px 180px 17px 180px;
}

header .down-bar .logo {
  display: block;
  position: absolute;
  left: -60px;
  top: -15px;
}

header .down-bar .logo span {
  display: inline-block;
  height: 52px;
  width: 52px;
  background-color: #F8F8F8;
  vertical-align: middle;
  margin-right: 14px;
  border-radius: 50%;
}

header .down-bar ul {
  display: block;
  margin: 0;
  padding: 0;
}

header .down-bar ul li {
  display: inline-block;
  vertical-align: middle;
}

header .down-bar ul li a {
  color: #101525;
  font-weight: 900;
  letter-spacing: 1px;
  line-height: 22px;
  text-transform: uppercase;
  text-decoration: none;
}

header .down-bar ul li a:hover {
  color: #F7796A;
}

header.only-menu + * {
  margin-top: -115px;
}

header.only-menu .down-bar.bg-white {
  background: #fff;
  box-shadow: 0 18px 35px 0 rgba(104, 110, 117, 0.1);
}

.header-menu {
  display: block;
  background: #F8F8F8;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  transform: translateY(-150%);
  z-index: 11;
  box-shadow: 0 18px 25px 0 rgba(94, 97, 102, 0.35);
  padding: 46px 120px 45px;
}

.header-menu.open {
  transform: translateY(0);
}

.header-menu .logo {
  display: inline-block;
  height: 42px;
  width: 42px;
  background-color: #E3EFFE;
  vertical-align: middle;
  border-radius: 50%;
}

.header-menu .logo + ul {
  display: inline-block;
  margin: 0;
  padding: 0;
}

.header-menu .logo + ul li {
  display: inline-block;
  vertical-align: middle;
  padding: 0 20px;
}

.header-menu .logo + ul li a {
  color: #101525;
  font-weight: 900;
  letter-spacing: 1px;
  line-height: 22px;
  text-decoration: none;
}

.header-menu .logo + ul li a:hover {
  color: #F7796A;
}

.header-menu .search-btn {
  color: #101525;
  font-size: 23px;
  font-weight: 900;
  letter-spacing: 1px;
  line-height: 22px;
  text-decoration: none;
}

.header-menu .search-btn:hover {
  color: #F7796A;
}

.header-menu .title {
  color: #101525;
  font-size: 30px;
  font-weight: 900;
  line-height: 44px;
  padding-top: 41px;
